Definition prep_frame (m : mem) (spq : Z) (j24 : list byte) (w24 w32 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) : Prop :=
  rw_cells rsegs m spq [CB 24 j24; C8 w24; C8 w32; C8 s9v; C8 s8v; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav].

(* [comment removed for export] *)
Lemma frame_head_merge : forall m A (u v : word) (j : list byte) rest,
  rw_cells rsegs m A (C8 u :: C8 v :: CB 8 j :: rest) -> rw_cells rsegs m A (CB 24 (le8 u ++ le8 v ++ j) :: rest).
Proof.
  intros m A u v j rest H. pose proof H as [[WF _] _]. cbn in WF. destruct WF as (_ & _ & L & WR).
  eapply rw_cells_reshape; [exact H| |].
  - cbn. split; [lia| exact WR].
  - cbn [cells_bytes cbytes]. rewrite <- !app_assoc. reflexivity.
Qed.

