Definition prep_tail_post (spq : Z) (gp tp : word) (s10 s11 : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav w24 w32 : word)
    (F : bvmap 5 word) (fc : bv 32) (res b : Z) (es : list mbe) (insz n x lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j24,
    ms' = MS (mkR rav (wz (spq + 128)) gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom rsegs)
    /\ munch [(lo, spq + 16); (res, res + 40)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo spq
    /\ prep_frame m' spq j24 w24 w32 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav
    /\ rw_cells rsegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
    /\ MBmid m' b es insz n x.

Definition prep_tail_stmt : Prop := forall (spq res b : Z) (es : list mbe) (insz n x lo : Z) (j24 rj : list byte)
    (rax : word) gp tp (t0 t1 t2 : word) (a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (w24 w32 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (F : bvmap 5 word) fc (m : mem),
  MBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  prep_frame m spq j24 w24 w32 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav ->
  rw_cells rsegs m res [CB 40 rj] -> spq + 128 <= res -> res + 40 <= b ->
  stk rsegs m lo spq -> lo + 16 <= spq -> hceil <= lo -> spq mod 8 = 0 ->
  bv_unsigned rav mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (prep_tail_post spq gp tp s10 s11 s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav w24 w32 F fc res b es insz n x lo m)
    (MS (mkR rax (wz spq) gp tp t0 t1 t2 (wz n) (wz res) a0 a1 a2 a3 a4 a5 a6 a7 (wz b) (wz (b + 8)) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_PREP_TAIL) fc None m (seg_rom rsegs)).
