Definition prep_attail_post (spq : Z) (gp tp s10 s11 : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (F : bvmap 5 word) (fc : bv 32) (res b : Z) (es : list mbe) (insz n x lo : Z) (W : list (Z * Z)) (m : mem) : machine_state -> Prop :=
  fun ms' => exists rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 t3 t4 t5 t6 m' j24,
    ms' = MS (mkR rax (wz spq) gp tp t0 t1 t2 (wz n) (wz res) a0 a1 a2 a3 a4 a5 a6 a7 (wz b) (wz (b + 8)) s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_PREP_TAIL) fc None m' (seg_rom rsegs)
    /\ munch W m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo spq
    /\ prep_frame m' spq j24 (wz (spq + 24)) (wz (spq + 24)) s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav
    /\ MBmid m' b es insz n x.

Lemma frame_head_merge1 : forall m A (u : word) (j : list byte) rest,
  rw_cells rsegs m A (C8 u :: CB 16 j :: rest) -> rw_cells rsegs m A (CB 24 (le8 u ++ j) :: rest).
Proof.
  intros m A u j rest H. pose proof H as [[WF _] _]. cbn in WF. destruct WF as (_ & L & WR).
  eapply rw_cells_reshape; [exact H| |].
  - cbn. split; [cbn in L; lia| exact WR].
  - cbn [cells_bytes cbytes]. rewrite <- !app_assoc. reflexivity.
Qed.

